[InitializeOnLoad]public static class GrandYardCheck{static GrandYardCheck(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("GrandYardCheck.request"))return;File.Delete("GrandYardCheck.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var yard=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var pad=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/YachtPortAtlas/Meshes/Grand Yard Helicopter Pad.asset");pad.uv=new[]{new Vector2(0,1),new Vector2(0,0),new Vector2(1,1),new Vector2(1,0)};EditorUtility.SetDirty(pad);AssetDatabase.SaveAssets();var points=yard.sharedMesh.vertices.Select(yard.transform.TransformPoint).ToArray();float top=points.Max(v=>v.y);var mat=yard.GetComponent<MeshRenderer>().sharedMaterial;int wrong=yard.GetComponentsInChildren<MeshRenderer>().Count(r=>r.sharedMaterial!=mat);var center=yard.GetComponent<Renderer>().bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,center+new Vector3(-110,180,-140),center,"Grand-Ground-Yard-With-Helipad"});File.WriteAllText("FinalEnvironmentRoadReview/GrandYardValidation.txt","yard top y="+top+"; horizontal top vertices="+points.Count(v=>Mathf.Abs(v.y-top)<.01f)+"; landing pad collider uses yard ground mesh="+(yard.GetComponent<MeshCollider>().sharedMesh==yard.sharedMesh)+"; non-shared materials="+wrong+"; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}}
